const std = @import("std");

const Color = enum { Red, Black };

const RBNode = struct {
    key: i32,
    color: Color,
    left: ?*RBNode,
    right: ?*RBNode,
};

fn isRed(n: ?*RBNode) bool {
    return if (n) |node| node.color == Color.Red else false;
}

fn flipColors(n: *RBNode) void {
    n.color = Color.Red;
    if (n.left) |l| l.color = Color.Black;
    if (n.right) |r| r.color = Color.Black;
}

pub fn main() !void {
    var n3 = RBNode{ .key = 30, .color = Color.Red, .left = null, .right = null };
    var n2 = RBNode{ .key = 20, .color = Color.Red, .left = null, .right = null };
    var n1 = RBNode{ .key = 10, .color = Color.Black, .left = null, .right = &n2 };
    n2.right = &n3;

    std.debug.print("Root: {} ({s})\n", .{n1.key, if (n1.color == Color.Red) "Red" else "Black"});
    std.debug.print("Right: {} ({s})\n", .{n2.key, if (n2.color == Color.Red) "Red" else "Black"});

    if (isRed(n2.right)) {
        std.debug.print("Right-right red chain detected\n", .{});
    }
}

